import os
from typing import Optional, Dict, Any

import requests


class CloudWatchMetricsComparator:
    def __init__(
        self,
        api_key: Optional[str] = None,
        app_key: Optional[str] = None,
        site: Optional[str] = None,
    ) -> None:
        self.api_key = api_key or os.environ["DD_API_KEY"]
        self.app_key = app_key or os.environ["DD_APP_KEY"]
        self.site = site or os.environ.get("DD_SITE", "datadoghq.com")
        self.base_url = f"https://api.{self.site}/api/v1"

    def _query_series(self, query: str, start_ts: int, end_ts: int) -> Dict[str, Any]:
        resp = requests.get(
            f"{self.base_url}/query",
            headers={
                "DD-API-KEY": self.api_key,
                "DD-APPLICATION-KEY": self.app_key,
            },
            params={
                "from": start_ts,
                "to": end_ts,
                "query": query,
            },
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def _extract_value(data: Dict[str, Any]) -> Optional[float]:
        series = data.get("series") or []
        if not series:
            return None

        pointlists = series[0].get("pointlist") or []
        values = [p[1] for p in pointlists if isinstance(p, list) and len(p) >= 2 and p[1] is not None]
        if not values:
            return None

        return float(values[-1])

    def compare(
        self,
        metric_name: str,
        filter_a: str,
        filter_b: str,
        start_ts: int,
        end_ts: int,
        aggregator: str = "avg",
        rollup_seconds: Optional[int] = None,
    ) -> Dict[str, Any]:
        query_a = f"{aggregator}:{metric_name}{{{filter_a}}}"
        query_b = f"{aggregator}:{metric_name}{{{filter_b}}}"

        if rollup_seconds:
            query_a += f".rollup({aggregator},{rollup_seconds})"
            query_b += f".rollup({aggregator},{rollup_seconds})"

        data_a = self._query_series(query_a, start_ts, end_ts)
        data_b = self._query_series(query_b, start_ts, end_ts)

        value_a = self._extract_value(data_a)
        value_b = self._extract_value(data_b)

        if value_a is None or value_b is None:
            raise ValueError("One or both metric queries returned no comparable values.")

        difference = value_a - value_b
        ratio = None if value_b == 0 else value_a / value_b

        return {
            "provider": "Datadog",
            "site": self.site,
            "metric_name": metric_name,
            "window": {
                "from": start_ts,
                "to": end_ts,
            },
            "resource_a": {
                "filter": filter_a,
                "query": query_a,
                "value": value_a,
            },
            "resource_b": {
                "filter": filter_b,
                "query": query_b,
                "value": value_b,
            },
            "comparison": {
                "difference": difference,
                "absolute_difference": abs(difference),
                "ratio_a_to_b": ratio,
                "greater": "a" if value_a > value_b else "b" if value_b > value_a else "equal",
            },
        }
